/**
 * Formula answers from an INDEPENDENT implementation.
 *
 * Generated by writing these formulas into an `.xlsx` with NO cached values,
 * letting LibreOffice compute them, and reading the results back.
 *
 * The "no cached values" part is load-bearing. LibreOffice COPIES a cached
 * value when one is present -- proved by planting a deliberately wrong one and
 * watching it survive the round trip. An oracle built from a workbook that
 * already carried values would have been our own arithmetic wearing someone
 * else's name.
 *
 *  Regenerating: `tools/formula-oracle.sh`. Do not hand-edit an expectation
 * to make a test pass -- the point of the file is that nobody here chose these
 * numbers.
 */
export interface OracleCase {
    /** The formula WITHOUT its leading `=`, as the document stores it. */
    readonly formula: string;
    /** What LibreOffice computed, rendered as the grid would show it. */
    readonly expected: string;
}

